prelude_alias_identity.source:
using {LegacyString,LegacyBuffer} from "legacy.fih";
using {CompatString,CompatBuffer} from "compat.fih";
using {CoreString,CoreBuffer} from "canonical.fih";
fn current_text(value:CoreString)->String {return value;}
fn current_buffer(value:LegacyBuffer)->ByteBuffer {return value;}
fn main()->i32 {
    let mut buffer=ByteBuffer.new();buffer.append_c_string("ab");
    let legacy:LegacyBuffer=buffer.copy();let compat:CompatBuffer=legacy.copy();let mut core:CoreBuffer=compat.copy();
    let text:String=LegacyString.from_bytes(core);let old:LegacyString=text.clone();
    let snapshot:CompatString=CoreString.from_bytes(current_buffer(legacy));
    let maybe:Option<LegacyString>=Option.Some(text.clone());
    let result:Result<CoreString,u8>=Result.Ok(maybe.unwrap());
    let values:[CompatString;1]=[result.unwrap()];
    let [value]=values;let joined=current_text(value).concat(LegacyString.new());
    if joined==text || !joined.equals(snapshot) {return 1;}
    if String.max_capacity()!=LegacyString.max_capacity() || String.max_capacity()!=ByteBuffer.max_capacity() {return 2;}
    core.set(0,120);let mut independent=compat.copy();independent.set(0,121);
    let raw=old.to_c_string().unwrap();
    printf("compat %ld %ld %ld %lu %lu\n",buffer==core,text==old,snapshot.equals(joined),buffer.byte_at(0),raw[0]);
    free(raw);return 0;
}
